},
"lighting": {
    "concept": "黄金时刻——太阳低悬在左侧地平线上方。近乎水平的暖琥珀色光线斜掠过整个场景。每一处凸起的表面都像着了火。每一道阴影都被拉得很长。空气本身都带着可见的暖意。这是最具戏剧性的自然光照条件——在此以文艺复兴时期明暗对照法绘画的庄重感来处理，转化为水墨与色彩。",

    "key_light": {
      "source": "落日，低悬于地平线，来自左侧",
      "color": "#FFD280 暖琥珀金",
      "direction": "近乎水平，从左向右斜掠",
      "effect_on_cowboy": "面部和身体的右侧被温暖照亮——每一道风霜刻下的皱纹、每一根胡茬都在金色光线中清晰可见。左侧陷入冷蓝紫色阴影。营造出戏剧性的半明半暗肖像。",
      "effect_on_environment": "长长的阴影向右延伸，横跨尘土飞扬的地面。朝向太阳的木质表面泛着琥珀色光芒。空气中的尘埃颗粒捕捉光线，如同漂浮的金色火花。"
    },

    "fill_light": {
      "source": "来自上方暮色天空的环境天光",
      "color": "#6B7B9B 冷蓝紫色",
      "effect": "以冷色调填充阴影区域。避免纯黑——你能看到阴影中的细节，但全部带有蓝紫色调。主光与补光之间的这种暖冷对比，正是营造出丰富层次感的关键。"
    },

    "accent_light": {
      "source": "酒馆内油灯的暖光，从摆动门和窗户中溢出",
      "color": "#FFA040 暖琥珀色",
      "effect": "在牛仔帽后部和肩部形成轮廓光。将他与背景分离。同时在地板门廊上投下几何形状的窗光矩形。"
    },

    "shadow_treatment": {
      "coverage": "阴影覆盖图像面积的45-55%",
      "cast_shadows": "牛仔的长影向右横跨整条街道。门廊挑檐在酒馆外立面上投下一道硬朗的水平阴影。椅腿投下细长的阴影线条。",
      "face_shadows": "半脸光照。右侧温暖且细节丰富。左侧冷调阴影——眼窝深陷，颧骨形成锐利的阴影边缘，胡茬点在明暗过渡中清晰可见。",
      "atmospheric": "可见的尘埃微粒漂浮在落日光束中。在光中呈金色，在阴影中不可见。营造出空气厚重而温暖的质感。"
    }
  },
{
  "scene": {
    "composition": "宽幅电影感画面。牛仔坐在略偏中心左侧——黄金分割点。酒馆门面占据背景右侧三分之二。尘土飞扬的开阔街道向左延伸，通向地平线与落日。这种不对称——右侧坚实的建筑，左侧空旷的虚无——强化了情感上的孤立。一个孤独的身影，立于文明（酒馆）与荒野（开阔沙漠）的交界处。",

    "the_cowboy": {
      "position": "坐在酒馆前廊一把粗糙的木椅上",
      "pose": "向后靠着，重心压在椅子后腿上。左脚靴子平放在门廊地板上。右脚踝交叉搭在左膝上——从容，不慌不忙。右手松松地握着一只矮威士忌杯，搁在右膝上。杯子已空了一半。左手搭在椅子扶手或大腿上。头微微低垂，但目光直视前方地平线——那是历经沧桑之人才有的千码凝视。肩膀宽阔但不紧绷。肢体语言在说：我在休息，但我从未失去警觉。",
      "face": "这必须是一张具体的脸，而不是泛泛的牛仔形象。中年，四十到五十多岁。方下巴，下颌线条透过胡茬清晰可见。深陷的眼睛藏在厚重的眉骨下——锐利、警觉，因落日强光而微微眯起。三天未刮的胡茬，深色中夹杂着下巴处的灰白。饱经日晒的皮肤——眼角放射出深深的鱼尾纹，额头横纹，法令纹已变成永久的沟壑。左颧骨上有一道愈合的伤疤——细长，发白，陈旧。鼻子因很久以前的骨折而微微歪斜，鼻梁上有一处隆起。薄唇抿成一条中性的线——不是皱眉，也不是微笑。这张脸经历了数十年艰苦的户外生活，每一道皱纹都写满了痕迹。",
      "clothing_detail": "宽檐牛仔帽，深色沾满灰尘的棕色，破旧不堪——帽冠有凹痕，帽檐微微卷曲且边缘磨损，帽带上可见一圈汗渍。褪色的米白色棉衬衫，袖子卷到前臂中段，露出晒成古铜色的前臂，青筋和肌腱清晰可见。衬衫外罩深色皮马甲，磨损严重——表面多处龟裂，接缝处可见缝线，有几处皮革因多年使用而变得哑光。褪色的深蓝灰色牛仔裤，膝盖和大腿处因磨损而颜色更浅，沾满灰尘。宽皮带配古铜色做旧带扣——带扣捕捉到落日的一束锐利光芒。右胯挂着一把左轮手枪——深色做旧皮质枪套，木质枪柄可见，一点钢光闪烁。深棕色皮靴，布满刮痕和刻痕，鞋跟略微磨平，脚踝处扣着马刺皮带。"
    },
"the_saloon": {
  "architecture": "经典老西部边境酒馆。两层木结构建筑，带假立面（外立面高出实际屋顶线，使其看起来更宏伟）。由粗锯木板建造，部分因年久而变形。入口上方有一块手绘招牌：深红色背景上用褪色的金色字母写着'SALOON'——油漆正在开裂，角落处剥落，其中一个字母比其他字母褪色得更厉害。",
  "entrance": "中央是摆动的半截门，微微敞开。透过缝隙，温暖的琥珀色光线向外溢出——那是油灯的光芒和里面的喧闹。你看不清内部，只能感受到那些门后蕴含的温暖与嘈杂。",
  "windows": "入口两侧各有一扇窗户。肮脏的玻璃透出里面的暖光。其中一块窗玻璃上有一道斜向裂纹。",
  "porch": "木质门廊横贯建筑整个宽度。木板饱经风霜——被阳光漂白的地方呈灰色，被人来人往磨得光滑的地方呈深棕色。一些木板微微变形，几颗钉头凸出。粗糙的原木柱子支撑着门廊的遮檐。",
  "details": "前方有一根拴马桩，上面系着一根马缰绳——绳子绷紧，暗示有一匹马刚好在画面之外。拴马桩旁有一个木制饮水槽，表面泛着绿色。门边有一个木桶。一切都覆盖着一层薄薄的沙漠尘土。"
},
"constraints": {
  "must_include": [
    "贯穿始终的粗黑墨水轮廓线清晰可见——这是带色彩的线稿艺术，不是绘画",
    "丰富的多层色彩，每个表面都有色调渐变",
    "所有阴影区域都有冷蓝紫色偏移（不仅仅是加深底色）",
    "夕阳直射处有温暖的琥珀金色光线",
    "极其精细的面部，具有具体的个人特征——伤疤、皱纹、骨骼结构",
    "材质区分——皮革、木材、金属、织物、皮肤看起来各不相同",
    "夕阳光束中的大气尘埃颗粒",
    "尘土飞扬的地面上长长而戏剧性的投影",
    "酒馆内部透出的暖光作为轮廓光/点缀光",
    "左侧广阔开放的空间与右侧坚实的酒馆结构形成对比"
  ],
  "must_avoid": [
    "任何形式的卡通或漫画风格",
    "动漫或日漫渲染惯例",
    "没有渐变的平涂填色",
    "掩盖墨水线条的柔和喷枪效果",
    "照片级写实——墨水绘画必须可见",
    "没有特征的通用面孔——这必须是一个具体的人",
    "任何看起来干净或崭新的东西——一切都要显示年代和磨损",
    "浑浊暗沉的色彩——夕阳提供丰富的暖光",
    "僵硬摆姿势的人物——自然放松的人体语言",
    "水彩透明感或晕染边缘技法"
  ]
},
"negative_prompt": "动漫、漫画、Q版、卡通、讽刺画、平涂色彩、赛璐璐上色、极简主义、照片级写实摄影、3D CGI 渲染、柔和喷枪、水彩、粉彩配色、潦草粗糙线条、大众脸、干净的新衣服、明亮霓虹、模糊、低分辨率、僵硬姿势、现代元素、矢量艺术、简单插画、儿童绘本风格、波普艺术、抽象"
}

